package com.nextfeet.nextfeet.repository; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; import com.nextfeet.nextfeet.model.Zapatilla; @Repository public class ZapatillaRepository implements ZapatillaDAO {private final JdbcTemplate db; public ZapatillaRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Zapatilla> map=(r,n)->new Zapatilla(r.getInt("id"),r.getString("sku"),r.getString("nombre"),r.getString("marca"),r.getBigDecimal("precio"),r.getString("descripcion"),r.getString("materiales"),r.getString("colores"),r.getString("imagen"),r.getObject("categoria_id",Integer.class),r.getString("estado")); public List<Zapatilla> catalogo(String q,String marca,Integer cat,Double min,Double max){StringBuilder s=new StringBuilder("select * from zapatilla where estado='ACTIVO'");List<Object> p=new ArrayList<>(); if(q!=null&&!q.isBlank()){s.append(" and (lower(nombre) like ? or lower(marca) like ? or lower(sku) like ?)");String x="%"+q.toLowerCase()+"%";p.add(x);p.add(x);p.add(x);} if(marca!=null&&!marca.isBlank()){s.append(" and lower(marca)=?");p.add(marca.toLowerCase());} if(cat!=null){s.append(" and categoria_id=?");p.add(cat);} if(min!=null){s.append(" and precio>=?");p.add(min);} if(max!=null){s.append(" and precio<=?");p.add(max);} s.append(" order by id desc");return db.query(s.toString(),map,p.toArray());} public List<Zapatilla> listar(){return db.query("select * from zapatilla order by id desc",map);} public Zapatilla obtener(Integer id){return db.query("select * from zapatilla where id=?",map,id).stream().findFirst().orElse(null);} public void crear(Zapatilla z){db.update("insert into zapatilla(sku,nombre,marca,precio,descripcion,materiales,colores,imagen,categoria_id,estado) values(?,?,?,?,?,?,?,?,?,?)",z.getSku(),z.getNombre(),z.getMarca(),z.getPrecio(),z.getDescripcion(),z.getMateriales(),z.getColores(),z.getImagen(),z.getCategoriaId(),"ACTIVO");} public void actualizar(Zapatilla z){db.update("update zapatilla set nombre=?,marca=?,precio=?,descripcion=?,materiales=?,colores=?,imagen=?,categoria_id=? where id=?",z.getNombre(),z.getMarca(),z.getPrecio(),z.getDescripcion(),z.getMateriales(),z.getColores(),z.getImagen(),z.getCategoriaId(),z.getId());} public void cambiarEstado(Integer id,String e){db.update("update zapatilla set estado=? where id=?",e,id);} public void eliminar(Integer id){db.update("delete from zapatilla where id=?",id);} public int stock(Integer id,String t){return db.queryForObject("select coalesce(cantidad,0) from stock_talla where zapatilla_id=? and talla=?",Integer.class,id,t)==null?0:db.queryForObject("select coalesce(cantidad,0) from stock_talla where zapatilla_id=? and talla=?",Integer.class,id,t);} public void ajustarStock(Integer id,String t,int d){Integer n=db.query("select cantidad from stock_talla where zapatilla_id=? and talla=?", (r,rowNum)->r.getInt(1), id,t).stream().findFirst().orElse(null); if(n==null)db.update("insert into stock_talla(zapatilla_id,talla,cantidad) values(?,?,?)",id,t,d);else db.update("update stock_talla set cantidad=? where zapatilla_id=? and talla=?",n+d,id,t);} }